  const incomeTax=num(result.netIncomeTax)/annualFactor,ni=num(result.nationalInsurance)/annualFactor,taxAtSource=num(result.taxAtSource)/annualFactor,provision=Math.max(0,incomeTax+ni-taxAtSource),afterTax=Math.max(0,monthlyTaxable-incomeTax-ni);
